package com.graduation.gym.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(MembershipPlanRepository plans){return args->{if(plans.count()==0){var x=new MembershipPlan();x.setName("30 天校园活力卡");x.setDurationDays(30);x.setPrice(new java.math.BigDecimal("199"));x.setDescription("器械区与有氧区不限次使用");x.setStatus("ACTIVE");plans.save(x);}};}}
